content.arguments:
{"command": "$rows = @()
foreach ($base in @($env:APPDATA, $env:LOCALAPPDATA)) {
  Get-ChildItem $base -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'DeepSeek|dsh' } | ForEach-Object {
    $s = (Get-ChildItem -Recurse -Force -File -ErrorAction SilentlyContinue $_.FullName | Measure-Object -Sum Length).Sum
    $rows += [pscustomobject]@{ Path = $_.FullName; MB = [math]::Round($s/1MB,1) }
  }
}
$rows | Format-Table -AutoSize
Write-Output "--- plugin state dirs ---"
foreach ($d in 'im','llm-deepseek','whale-roles','whale-audio') {
  Get-ChildItem "C:\Users\24380\.dsh\$d" -Force -ErrorAction SilentlyContinue | ForEach-Object { "{0,-16} {1}" -f $d, $_.Name }
}", "description": "Check app data folders and plugin state dirs"}

