content.arguments:
{"content": "<#
.SYNOPSIS
    在新电脑上还原 Export-DshBundle.ps1 打出来的迁移包。

.DESCRIPTION
    顺序很重要：
      1) 新电脑先装同版本 DSH（本机 0.2.2-rc.5），装完**先不要打开**
      2) 本机完全退出 DSH
      3) 运行本脚本
      4) 打开 DSH，检查插件、会话是否都在

    脚本做的事：
      - 把 work\<name> 还原到 -WorkspaceRoot 下
      - 把 dsh-home 合并进 %USERPROFILE%\.dsh（覆盖同名文件，不删多余文件）
      - 修 profiles\desktop\package.json 里 dsh-pet-balance 的 link: 绝对路径
      - 重建 node_modules\dsh-pet-balance 的目录联接（junction）
      - 如果新机工作区路径变了，把 sessions 下按旧路径命名的目录改名成新路径

.EXAMPLE
    .\Restore-DshBundle.ps1 -Bundle E:\dsh-migrate -WorkspaceRoot 'D:\BaiduSyncdisk\000'

.EXAMPLE
    # 先看看会做什么
    .\Restore-DshBundle.ps1 -Bundle E:\dsh-migrate -PlanOnly
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [string]$Bundle,

    [string]$WorkspaceRoot = 'D:\BaiduSyncdisk\000',

    [string]$DshHome = (Join-Path $env:USERPROFILE '.dsh'),

    # 旧机器上的工作区根；只有在路径变了、需要改会话目录名时才要填
    [string]$OldWorkspaceRoot,

    [string[]]$Workspaces = @('DSH', 'bodybuilding', '兵哥烧烤', '烧烤'),

    [switch]$PlanOnly,
    [switch]$Force
)

$ErrorActionPreference = 'Stop'
$Bundle = [System.IO.Path]::GetFullPath($Bundle)
if (-not (Test-Path -LiteralPath $Bundle)) { throw "迁移包不存在：$Bundle" }
if (-not (Test-Path -LiteralPath (Join-Path $Bundle 'MANIFEST.txt'))) {
    Write-Warning '包里没有 MANIFEST.txt，可能不是本脚本生成的迁移包，继续但请自行确认内容。'
}

$running = @(Get-Process -ErrorAction SilentlyContinue |
             Where-Object { $_.ProcessName -like 'DeepSeek Harness*' })
if ($running.Count -gt 0 -and -not $Force) {
    throw "DSH 正在运行（PID: $($running.Id -join ', ')）。请先完全退出，或加 -Force。"
}

function Invoke-RobocopyBack {
    param([string]$Source, [string]$Dest)
    if (-not (Test-Path -LiteralPath $Source)) { Write-Warning "包内缺少：$Source"; return }
    New-Item -ItemType Directory -Path $Dest -Force | Out-Null
    Write-Host "  $Source -> $Dest" -ForegroundColor DarkGray
    & robocopy.exe $Source $Dest /E /XJ /R:1 /W:1 /MT:16 /COPY:DAT /DCOPY:DAT /NFL /NDL /NJH /NJS /NP | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "robocopy 失败（退出码 $LASTEXITCODE）：$Source" }
}

Write-Host ''
Write-Host "迁移包   : $Bundle" -ForegroundColor Cyan
Write-Host "工作区根 : $WorkspaceRoot" -ForegroundColor Cyan
Write-Host "DSH 家目录: $DshHome" -ForegroundColor Cyan
Write-Host ''

# ------------------------------------------------ 1. 工作区
Write-Host '[1/4] 还原工作区目录' -ForegroundColor Green
foreach ($w in $Workspaces) {
    $src = Join-Path $Bundle "work\$w"
    if (-not (Test-Path -LiteralPath $src)) { Write-Host "  跳过 $w（包里没有）" -ForegroundColor DarkGray; continue }
    if ($PlanOnly) { Write-Host "  计划：$src -> $(Join-Path $WorkspaceRoot $w)" }
    else          { Invoke-RobocopyBack -Source $src -Dest (Join-Path $WorkspaceRoot $w) }
}

# ------------------------------------------------ 2. DSH 家目录
Write-Host '[2/4] 还原 DSH 家目录' -ForegroundColor Green
$srcHome = Join-Path $Bundle 'dsh-home'
if ($PlanOnly) { Write-Host "  计划：$srcHome -> $DshHome" }
else          { Invoke-RobocopyBack -Source $srcHome -Dest $DshHome }

# ------------------------------------------------ 3. 修 profile 里的绝对路径
Write-Host '[3/4] 修正个人插件的软链路径' -ForegroundColor Green
$petSrc   = Join-Path (Join-Path $WorkspaceRoot 'DSH') 'pet-balance'
$petLink  = Join-Path $DshHome 'profiles\desktop\node_modules\dsh-pet-balance'
$pkgJson  = Join-Path $DshHome 'profiles\desktop\package.json'

if (Test-Path -LiteralPath $pkgJson) {
    $text = Get-Content -LiteralPath $pkgJson -Raw -Encoding UTF8
    $want = 'link:' + ($petSrc -replace '\\', '/')
    $new  = [regex]::Replace(
        $text,
        '("dsh-pet-balance"\s*:\s*")link:[^"]*(")',
        { param($m) $m.Groups[1].Value + $want + $m.Groups[2].Value })
    if ($new -ne $text) {
        if ($PlanOnly) { Write-Host "  计划：package.json 中 dsh-pet-balance -> $want" }
        else {
            Set-Content -LiteralPath $pkgJson -Value $new -Encoding UTF8 -NoNewline
            Write-Host "  package.json 已更新：$want" -ForegroundColor DarkGray
        }
    } else {
        Write-Host '  package.json 里的链接已正确，无需修改' -ForegroundColor DarkGray
    }
} else {
    Write-Warning "找不到 $pkgJson —— DSH 是否已安装并运行过一次？还原家目录前请先启动一次 DSH 以生成 profile。"
}

if (Test-Path -LiteralPath $petSrc) {
    if ($PlanOnly) {
        Write-Host "  计划：重建 junction $petLink -> $petSrc"
    } else {
        if (Test-Path -LiteralPath $petLink) {
            $item = Get-Item -LiteralPath $petLink -Force
            if ($item.LinkType) {
                # junction 必须用 rmdir 删除，Remove-Item -Recurse 会钻进目标目录
                & cmd.exe /c rmdir "$petLink" | Out-Null
                Write-Host "  已移除旧链接 $($item.LinkType)" -ForegroundColor DarkGray
            } else {
                Remove-Item -LiteralPath $petLink -Recurse -Force
                Write-Host '  已移除旧的真实目录' -ForegroundColor DarkGray
            }
        }
        New-Item -ItemType Directory -Path (Split-Path $petLink -Parent) -Force | Out-Null
        & cmd.exe /c mklink /J "$petLink" "$petSrc" | Out-Null
        if ($LASTEXITCODE -ne 0) { throw "mklink /J 失败（退出码 $LASTEXITCODE）：$petLink -> $petSrc" }
        $ok = Test-Path -LiteralPath (Join-Path $petLink 'package.json')
        Write-Host "  junction 已重建，自检：$(if ($ok) {'通过' } else { '异常——链接存在但读不到 package.json' })" `
                    -ForegroundColor $(if ($ok) { 'DarkGray' } else { 'Red' })
    }
} else {
    Write-Warning "找不到插件目录 $petSrc（'DSH' 工作区没还原？），跳过 junction 重建"
}

# ------------------------------------------------ 4. 会话目录改名（路径变了才需要）
Write-Host '[4/4] 会话目录与工作区路径对齐' -ForegroundColor Green
function ConvertTo-SessionDirName {
    param([string]$Path)
    '--' + (($Path -replace ':', '') -replace '\\', '-') + '--'
}
if ($OldWorkspaceRoot -and ($OldWorkspaceRoot -ne $WorkspaceRoot)) {
    $sess = Join-Path $DshHome 'sessions'
    foreach ($w in $Workspaces) {
        $oldName = ConvertTo-SessionDirName (Join-Path $OldWorkspaceRoot $w)
        $newName = ConvertTo-SessionDirName (Join-Path $WorkspaceRoot $w)
        $oldPath = Join-Path $sess $oldName
        if ((Test-Path -LiteralPath $oldPath) -and ($oldName -ne $newName)) {
            if ($PlanOnly) { Write-Host "  计划：$oldName -> $newName" }
            else {
                $newPath = Join-Path $sess $newName
                if (Test-Path -LiteralPath $newPath) { Remove-Item -LiteralPath $newPath -Recurse -Force }
                Rename-Item -LiteralPath $oldPath -NewName $newName
                Write-Host "  已改名：$oldName -> $newName" -ForegroundColor DarkGray
            }
        }
    }
} else {
    Write-Host '  路径未变，无需改名（如果新电脑路径不同，用 -OldWorkspaceRoot 重跑本步）' -ForegroundColor DarkGray
}

# ------------------------------------------------ 收尾
Write-Host ''
