content.arguments:
{"command": "$ErrorActionPreference='Continue'
$pkg = 'C:\Users\24380\.dsh\profiles\desktop\package.json'
$link = 'C:\Users\24380\.dsh\profiles\desktop\node_modules\dsh-pet-balance'
$newTarget = 'D:\Work\DSH\pet-balance'
$oldTarget = 'D:\BaiduSyncdisk\000\DSH\pet-balance'

# 1) package.json
$raw = [System.IO.File]::ReadAllText($pkg)
if ($raw -match '"dsh-pet-balance"\s*:\s*"link:[^"]*"') {
  $new = [regex]::Replace($raw, '("dsh-pet-balance"\s*:\s*")link:[^"]*(")', { param($m) $m.Groups[1].Value + ('link:' + ($newTarget -replace '\\','/')) + $m.Groups[2].Value })
  [System.IO.File]::WriteAllText($pkg, $new, (New-Object System.Text.UTF8Encoding($false)))
  'package.json: ' + (Select-String -LiteralPath $pkg -Pattern 'dsh-pet-balance' | Select-Object -First 1).Line.Trim()
} else { 'package.json: 未找到 link 行' }

# 2) junction
$it = Get-Item $link -Force -ErrorAction SilentlyContinue
'junction 现状: ' + $(if ($it) { $it.LinkType + ' -> ' + $it.Target } else { '不存在' })
if (Test-Path $newTarget) {
  try {
    & cmd.exe /c rmdir "$link" | Out-Null
    & cmd.exe /c mklink /J "$link" "$newTarget" | Out-Null
    $ok = Test-Path (Join-Path $link 'package.json')
    'junction 重建: ' + $(if ($ok) { 'OK -> ' + $newTarget } else { 'FAILED' })
