content.arguments:
{"command": "Get-ScheduledTask | Where-Object { $_.TaskName -like 'DSH-Shangpu-*' } | ForEach-Object {
  $i = $_ | Get-ScheduledTaskInfo
  $a = $_.Actions | ForEach-Object { "$($_.Execute) $($_.Arguments)" }
  [pscustomobject]@{ Task=$_.TaskName; State=$_.State; Schedule=($_.Triggers | ForEach-Object { $_.CimClass.CimClassName -replace 'MSFT_Task','' }) -join ','; Action=($a -join ' | '); Last=$i.LastRunTime; Result=$i.LastTaskResult }
} | Format-List", "description": "Inspect Shangpu scheduled task actions"}

