{"command": "$dir = 'D:\Work\兵哥烧烤\meituan-agent\tasks'
New-Item -ItemType Directory -Path $dir -Force | Out-Null
foreach ($n in 'DSH-Shangpu-Daily','DSH-Shangpu-Refresh30','DSH-Shangpu-Web','DSH-Shangpu-WebWatch','DSH-Shangpu-UnblockHourly') {
  $xml = schtasks /Query /TN $n /XML 2>$null
  if ($LASTEXITCODE -eq 0) { [System.IO.File]::WriteAllText((Join-Path $dir "$n.xml"), ($xml -join "`r`n"), (New-Object System.Text.UnicodeEncoding($false,$true))) ; "$n 导出 OK" } else { "$n 导出失败" }
}
Get-ChildItem $dir | Select-Object Name,Length
'--- 触发摘要 ---'
foreach ($n in 'DSH-Shangpu-Daily','DSH-Shangpu-Refresh30','DSH-Shangpu-WebWatch','DSH-Shangpu-UnblockHourly') {
  [xml]$x = Get-Content (Join-Path $dir "$n.xml") -Raw
  $t = $x.Task.Triggers.InnerXml -replace '\s+',' '
  "$n :: $t"
}", "description": "Export task XMLs and summarize triggers"}

