{"command": "$ig='D:\Work\.stignore'
$c=[System.IO.File]::ReadAllText($ig)
$add = "// SQLite WAL/SHM`r`n**/*.db-wal`r`n**/*.db-shm`r`n`r`n"
if ($c -notmatch 'db-wal') { $c = $add + $c }
$bytes=[System.Text.UTF8Encoding]::new($false).GetBytes($c)
try{
  $fs=[System.IO.FileStream]::new($ig,'Open','Write','ReadWrite')
  $fs.SetLength(0); $fs.Write($bytes,0,$bytes.Length); $fs.Flush($true); $fs.Close()
