content.arguments:
{"command": "$script = @'
const fs = require('node:fs'); const path = require('node:path');
const root = path.join(process.env.DSH_INSTALL_DIR, 'docs', 'user');
const terms = ['同步','sync','多设备','远端','remote session','云'];
const hits = [];
function walk(d){ for (const e of fs.readdirSync(d,{withFileTypes:true})) { const p = path.join(d,e.name);
  if (e.isDirectory()) walk(p);
  else if (e.name.endsWith('.md')) { const s = fs.statSync(p); if (s.size > 1024*1024) continue;
    const t = fs.readFileSync(p,'utf8'); t.split('\n').forEach((line,i)=>{ for (const term of terms) if (line.toLowerCase().includes(term.toLowerCase())) { hits.push(p.replace(root,'') + ':' + (i+1) + '  ' + line.trim().slice(0,160)); break; } }); } } }
walk(root);
console.log(hits.slice(0,60).join('\n'));
console.log('TOTAL', hits.length);
'@
$start = [System.Diagnostics.ProcessStartInfo]::new($env:DSH_NODE_EXECUTABLE)
foreach ($a in @('-e', $script)) { $start.ArgumentList.Add($a) }
$start.Environment['ELECTRON_RUN_AS_NODE'] = '1'
$start.UseShellExecute = $false; $start.RedirectStandardOutput = $true; $start.RedirectStandardError = $true
$start.StandardOutputEncoding = [System.Text.Encoding]::UTF8
$p = [System.Diagnostics.Process]::Start($start)
$out = $p.StandardOutput.ReadToEnd(); $err = $p.StandardError.ReadToEnd(); $p.WaitForExit()
$out; if ($err) { 'ERR: ' + $err.Substring(0, [Math]::Min(800,$err.Length)) }", "description": "Grep installed docs for sync keywords", "timeoutMs": 120000}

