            Warn2 '请先托盘退出 DSH，然后重新运行本脚本（或单独跑 Restore-DshBundle.ps1）。'
            Write-Host ''
            Write-Host '    powershell -ExecutionPolicy Bypass -File ' -NoNewline
            Write-Host "`"$restore`" -Bundle `"$Bundle`" -WorkspaceRoot `"$WorkRoot`"" -ForegroundColor White
        } else {
            if ($PlanOnly) { Info "将执行: $restore -Bundle $Bundle -WorkspaceRoot $WorkRoot" }
            else {
                & powershell -NoProfile -ExecutionPolicy Bypass -File $restore -Bundle $Bundle -WorkspaceRoot $WorkRoot
                if ($LASTEXITCODE -ne 0) { throw "还原失败（退出码 $LASTEXITCODE）" }
                Ok '~\.dsh 已还原'
            }
        }
    }
}

# ---------------------------------------------------------------- 4. 烧烤
if ($BbqSource) {
    Step 4 '一次性复制 烧烤'
    if (-not (Test-Path $BbqSource)) { throw "找不到烧烤来源：$BbqSource" }
    $dst = Join-Path $WorkRoot '烧烤'
    Info "$BbqSource -> $dst"
    if (-not $PlanOnly) {
        $rc = @($BbqSource, $dst, '/E', '/XJ', '/R:1', '/W:1', '/MT:16', '/NFL', '/NDL', '/NP')
        & robocopy @rc | Out-Null
        if ($LASTEXITCODE -ge 8) { throw "robocopy 失败（退出码 $LASTEXITCODE）" }
        Ok '烧烤 已复制（不进同步，老机的 .stignore 会跳过它）'
    }
}

# ---------------------------------------------------------------- 5. 采集任务
if (-not $SkipTasks) {
    Step 5 '采集计划任务'
    $setup = Join-Path $WorkRoot '兵哥烧烤\meituan-agent\setup_tasks.ps1'
    if (Test-Path $setup) {
        if ($PlanOnly) { Info "将执行: $setup -WorkRoot $WorkRoot" }
        else {
            & powershell -NoProfile -ExecutionPolicy Bypass -File $setup -WorkRoot $WorkRoot
            Ok '采集任务已创建（若缺 python，需先打开一次 DSH）'
        }
    } else {
        Warn2 "还没同步到 $setup —— 等 Syncthing 把文件拉下来后再跑这一步"
    }
}

# ---------------------------------------------------------------- 收尾
Write-Host "`n================ 还需要手动做的 ================" -ForegroundColor Yellow
Write-Host "1. 老电脑 Syncthing (http://127.0.0.1:8384)："
Write-Host "   · 接受新设备（会弹『新设备想连接』）"
Write-Host "   · 接受 work 文件夹共享"
if (-not $SkipRestore) {
    Write-Host "2. 装 DSH 0.2.2-rc.5（全新安装，装完别打开），重跑本脚本还原 ~\.dsh"
}
Write-Host "3. 微信重新绑定后更新两个 config："
Write-Host "   $WorkRoot\兵哥烧烤\meituan-agent\config.json"
Write-Host "   $WorkRoot\bodybuilding\scripts\coach_config.json"
Write-Host "4. 重登美团/饿了么：cd $WorkRoot\兵哥烧烤\meituan-agent; .\start-browser.ps1"
Write-Host "================================================" -ForegroundColor Yellow
", "file_path": "D:\Work\DSH\migrate\Bootstrap-NewPc.ps1"}

