{"content": "<#
.SYNOPSIS
    新电脑一键引导：装 Syncthing、连上老电脑、建忽略规则、还原 DSH、建采集任务。

.DESCRIPTION
    对应《同步说明.md》里的 7 步，除了"装 DSH 本身"和"两边各点一次接受"之外全部自动完成：

      1. winget 安装 Syncthing 并后台启动
      2. 读出新机的设备 ID，把老电脑加为远程设备、创建 work 文件夹（等老机点接受）
      3. 写 D:\Work\.stignore（这份文件不会跟 Syncthing 同步，必须本机建）
      4. 建开机自启快捷方式
      5. 还原 ~\.dsh（调用迁移包里的 Restore-DshBundle.ps1；要求 DSH 已关闭）
      6. 把 烧烤 从 U 盘/移动硬盘一次性复制过来（可选）
      7. 重建美团/饿了么采集计划任务

    唯一不能自动的是"接受"：老电脑 Syncthing 里要接受新设备与 work 文件夹，
    否则两边不会开始传。脚本跑完会打印提示。

.PARAMETER Bundle
    迁移包目录（含 dsh-home\ 与 Restore-DshBundle.ps1）。不给就跳过还原 ~\.dsh。

.PARAMETER BbqSource
    烧烤 的来源路径，例如 E:\Work\烧烤。给了就同步复制到 <WorkRoot>\烧烤。

.EXAMPLE
    # 插上 U 盘，盘符是 E:，迁移包在 E:\dsh-migrate
    powershell -ExecutionPolicy Bypass -File E:\dsh-migrate\Bootstrap-NewPc.ps1 `
        -Bundle E:\dsh-migrate -BbqSource E:\Work\烧烤
#>
[CmdletBinding()]
param(
    [string]$WorkRoot    = 'D:\Work',
    [string]$OldDeviceId = 'FF4WBCI-5MKFPPO-XLVMEI2-OJGQZZL-DV5DN2K-5YJGO57-YS24YXY-P7WCSAA',
    [string]$Bundle,
    [string]$BbqSource,
    [switch]$SkipSyncthing,
    [switch]$SkipRestore,
    [switch]$SkipTasks,
    [switch]$PlanOnly
)

$ErrorActionPreference = 'Stop'
function Step($n, $t) { Write-Host "`n[$n] $t" -ForegroundColor Cyan }
function Ok($m)   { Write-Host "    ✓ $m" -ForegroundColor Green }
function Info($m) { Write-Host "    · $m" -ForegroundColor DarkGray }
function Warn2($m){ Write-Host "    ! $m" -ForegroundColor Yellow }

$gui = 'http://127.0.0.1:8384'

# ---------------------------------------------------------------- 1. Syncthing
if (-not $SkipSyncthing) {
    Step 1 'Syncthing'
    $exe = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter 'syncthing.exe' -ErrorAction SilentlyContinue |
           Select-Object -First 1 -ExpandProperty FullName
    if (-not $exe) {
        $exe = Get-ChildItem "$env:ProgramFiles\Syncthing","${env:ProgramFiles(x86)}\Syncthing" -Filter 'syncthing.exe' -ErrorAction SilentlyContinue |
               Select-Object -First 1 -ExpandProperty FullName
    }
    if (-not $exe) {
        Info '未安装，用 winget 安装…'
        if (-not $PlanOnly) {
            & winget install --id Syncthing.Syncthing -e --accept-source-agreements --accept-package-agreements --silent 2>&1 |
                Select-Object -Last 5 | ForEach-Object { Info $_ }
            $exe = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter 'syncthing.exe' -ErrorAction SilentlyContinue |
                   Select-Object -First 1 -ExpandProperty FullName
        }
    }
    if ($exe) { Ok "syncthing: $exe" } elseif (-not $PlanOnly) { throw 'Syncthing 安装失败：请手工 winget install Syncthing.Syncthing' }

    # 配置目录
    $cfgDir = Join-Path $env:LOCALAPPDATA 'Syncthing'
    $cfgFile = Join-Path $cfgDir 'config.xml'

    if (-not $PlanOnly) {
        $running = (Get-Process syncthing -ErrorAction SilentlyContinue) -ne $null
        if (-not $running -and $exe) {
            Start-Process -FilePath $exe -ArgumentList 'serve','--no-browser','--no-restart' -WindowStyle Hidden
            Info '已后台启动，等配置生成…'
        }
        for ($i = 0; $i -lt 40; $i++) {
            Start-Sleep -Seconds 1
            if (Test-Path $cfgFile) { try { Invoke-RestMethod "$gui/rest/noauth/health" -TimeoutSec 2 | Out-Null; break } catch {} }
        }
    }

    # 开机自启
    $startup = [Environment]::GetFolderPath('Startup')
    $lnk = Join-Path $startup 'Syncthing.lnk'
    if ($exe -and -not (Test-Path $lnk) -and -not $PlanOnly) {
        $ws = New-Object -ComObject WScript.Shell
        $s = $ws.CreateShortcut($lnk)
        $s.TargetPath = $exe
        $s.Arguments = 'serve --no-browser --no-restart'
        $s.WindowStyle = 7
        $s.Description = 'Syncthing 后台同步'
        $s.Save()
        Ok "开机自启: $lnk"
    } elseif (Test-Path $lnk) { Ok '开机自启已存在' }

    if (-not $PlanOnly) {
        if (-not (Test-Path $cfgFile)) { throw "没等到 Syncthing 配置：$cfgFile" }
        [xml]$cfg = [System.IO.File]::ReadAllText($cfgFile)
        $apiKey = $cfg.configuration.gui.apikey
        $myId   = $cfg.configuration.device.id
        $H = @{ 'X-API-Key' = $apiKey }
        Ok "本机设备 ID: $myId"
        Write-Host "`n    把下面这行 ID 填到老电脑 Syncthing 的『添加远程设备』：" -ForegroundColor Yellow
        Write-Host "        $myId" -ForegroundColor White

        # 加老电脑为远程设备
        $devices = Invoke-RestMethod "$gui/rest/config/devices" -Headers $H
        if (-not ($devices | Where-Object { $_.deviceID -eq $OldDeviceId })) {
            $body = @{ deviceID = $OldDeviceId; name = 'old-pc'; addresses = @('dynamic'); compression = 'metadata' } |
                    ConvertTo-Json -Depth 5
            Invoke-RestMethod "$gui/rest/config/devices" -Method Post -Headers $H -ContentType 'application/json' -Body $body | Out-Null
            Ok '已把老电脑加入远程设备（等老机接受）'
        } else { Ok '老电脑已在设备列表' }

        # 文件夹 work
        $folders = Invoke-RestMethod "$gui/rest/config/folders" -Headers $H
        $f = $folders | Where-Object { $_.id -eq 'work' }
        if (-not $f) {
            if (-not (Test-Path $WorkRoot)) { New-Item -ItemType Directory -Path $WorkRoot -Force | Out-Null; Ok "已建 $WorkRoot" }
            $body = @{
                id = 'work'; label = 'work'; path = $WorkRoot; type = 'sendreceive'
                devices = @(@{ deviceID = $OldDeviceId; introducedBy = '' }, @{ deviceID = $myId; introducedBy = '' })
                fsWatcherEnabled = $true; fsWatcherDelayS = 10
                versioning = @{ type = 'staggered'; params = @{ maxAge = '2592000' } }
            } | ConvertTo-Json -Depth 8
            Invoke-RestMethod "$gui/rest/config/folders" -Method Post -Headers $H -ContentType 'application/json' -Body $body | Out-Null
            Ok "已创建文件夹 work -> $WorkRoot（等老机共享）"
        } else { Ok "文件夹 work 已存在 -> $($f.path)" }
    }

    # ---------------------------------------------------------------- 2. .stignore
    Step 2 '.stignore'
    $stig = Join-Path $WorkRoot '.stignore'
    if (-not (Test-Path $stig)) {
        if (-not (Test-Path $WorkRoot)) { New-Item -ItemType Directory -Path $WorkRoot -Force | Out-Null }
        $content = @'
// SQLite WAL/SHM
**/*.db-wal
**/*.db-shm

// ---- 机器本地状态：浏览器登录态、日志、缓存，绝不能互相同步 ----
/兵哥烧烤/meituan-agent/edge-profile
/兵哥烧烤/meituan-agent/edge-profile-silent
/兵哥烧烤/meituan-agent/edge-profile-backup
/兵哥烧烤/meituan-agent/logs
/兵哥烧烤/meituan-agent/data/wechat/*.exe
/兵哥烧烤/logs

// ---- 通用临时文件 ----
**/__pycache__
**/*.pyc
**/.git
**/.venv
**/node_modules
**/.dsh-acl-recovery
/烧烤
/DSH/migrate/_selftest
/DSH/migrate/_restoretest
/DSH/migrate/_fakehome*
**/~$*
**/*.tmp
**/Thumbs.db
**/desktop.ini
**/.DS_Store
'@
        if (-not $PlanOnly) {
            [System.IO.File]::WriteAllText($stig, $content, (New-Object System.Text.UTF8Encoding($false)))
            Ok "写入 $stig"
        }
    } else { Ok ".stignore 已存在（未覆盖）" }
}

# ---------------------------------------------------------------- 3. 还原 ~\.dsh
if (-not $SkipRestore) {
    Step 3 '还原 DSH 家目录'
    if (-not $Bundle) {
        Warn2 '没给 -Bundle，跳过。手动：Restore-DshBundle.ps1 -Bundle <迁移包>'
    } else {
        $restore = Join-Path $Bundle 'Restore-DshBundle.ps1'
        if (-not (Test-Path $restore)) { throw "迁移包里没有 Restore-DshBundle.ps1：$Bundle" }
        $dsh = Get-Process 'DeepSeek Harness' -ErrorAction SilentlyContinue
        if ($dsh) {
            Warn2 'DSH 正在运行，profile 被占用，无法还原。'
            Warn2 '请先托盘退出 DSH，然后重新运行本脚本（或单独跑 Restore-DshBundle.ps1）。'
            Write-Host ''
            Write-Host '    powershell -ExecutionPolicy Bypass -File ' -NoNewline
            Write-Host "`"$restore`" -Bundle `"$Bundle`" -WorkspaceRoot `"$WorkRoot`"" -ForegroundColor White
        } else {
            if ($PlanOnly) { Info "将执行: $restore -Bundle $Bundle -WorkspaceRoot $WorkRoot" }
            else {
                & powershell -NoProfile -ExecutionPolicy Bypass -File $restore -Bundle $Bundle -WorkspaceRoot $WorkRoot
                if ($LASTEXITCODE -ne 0) { throw "还原失败（退出码 $LASTEXITCODE）" }
                Ok '~\.dsh 已还原'
            }
        }
    }
}

# ---------------------------------------------------------------- 4. 烧烤
if ($BbqSource) {
    Step 4 '一次性复制 烧烤'
    if (-not (Test-Path $BbqSource)) { throw "找不到烧烤来源：$BbqSource" }
    $dst = Join-Path $WorkRoot '烧烤'
    Info "$BbqSource -> $dst"
    if (-not $PlanOnly) {
        $rc = @($BbqSource, $dst, '/E', '/XJ', '/R:1', '/W:1', '/MT:16', '/NFL', '/NDL', '/NP')
        & robocopy @rc | Out-Null
        if ($LASTEXITCODE -ge 8) { throw "robocopy 失败（退出码 $LASTEXITCODE）" }
        Ok '烧烤 已复制（不进同步，老机的 .stignore 会跳过它）'
    }
}

# ---------------------------------------------------------------- 5. 采集任务
if (-not $SkipTasks) {
    Step 5 '采集计划任务'
    $setup = Join-Path $WorkRoot '兵哥烧烤\meituan-agent\setup_tasks.ps1'
    if (Test-Path $setup) {
        if ($PlanOnly) { Info "将执行: $setup -WorkRoot $WorkRoot" }
        else {
            & powershell -NoProfile -ExecutionPolicy Bypass -File $setup -WorkRoot $WorkRoot
            Ok '采集任务已创建（若缺 python，需先打开一次 DSH）'
        }
    } else {
        Warn2 "还没同步到 $setup —— 等 Syncthing 把文件拉下来后再跑这一步"
    }
}

# ---------------------------------------------------------------- 收尾
Write-Host "`n================ 还需要手动做的 ================" -ForegroundColor Yellow
Write-Host "1. 老电脑 Syncthing (http://127.0.0.1:8384)："
Write-Host "   · 接受新设备（会弹『新设备想连接』）"
Write-Host "   · 接受 work 文件夹共享"
if (-not $SkipRestore) {
    Write-Host "2. 装 DSH 0.2.2-rc.5（全新安装，装完别打开），重跑本脚本还原 ~\.dsh"
}
Write-Host "3. 微信重新绑定后更新两个 config："
Write-Host "   $WorkRoot\兵哥烧烤\meituan-agent\config.json"
Write-Host "   $WorkRoot\bodybuilding\scripts\coach_config.json"
Write-Host "4. 重登美团/饿了么：cd $WorkRoot\兵哥烧烤\meituan-agent; .\start-browser.ps1"
Write-Host "================================================" -ForegroundColor Yellow
", "file_path": "D:\Work\DSH\migrate\Bootstrap-NewPc.ps1"}

