New step 1 code:

```
# ---------------------------------------------------------------- 1. Syncthing
if (-not $SkipSyncthing) {
    Step 1 'Syncthing'
    $cands = @(
        $SyncthingExe,
        (Join-Path $env:LOCALAPPDATA 'Syncthing\syncthing.exe'),
        (Join-Path $env:LOCALAPPDATA 'Programs\Syncthing\syncthing.exe'),
        (Join-Path $env:ProgramFiles 'Syncthing\syncthing.exe'),
        (Join-Path ${env:ProgramFiles(x86)} 'Syncthing\syncthing.exe')
    )
    $exe = $cands | Where-Object { $_ -and (Test-Path $_) } | Select-Object -First 1
    if (-not $exe) {
        $exe = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter 'syncthing.exe' -ErrorAction SilentlyContinue |
               Select-Object -First 1 -ExpandProperty FullName
    }
    if ($exe) { Info "已安装：$exe" }
    elseif ($PlanOnly) { Info '未安装，正式运行时会用 winget 安装' }
    else {
        $wg = Get-Command winget -ErrorAction SilentlyContinue
        if (-not $wg) { throw '找不到 winget（Windows 10 21H2 以下或应用安装程序被移除）。请手工装 Syncthing：https://github.com/syncthing/syncthing/releases 解压后加 -SyncthingExe <路径>。' }
        Info '未安装，用 winget 安装（1–3 分钟，请勿关闭窗口）…'
        $log = Join-Path $env:TEMP 'syncthing-winget.log'
        Remove-Item $log,"$log.err" -ErrorAction SilentlyContinue
        $p = Start-Process -FilePath $wg.Source -ArgumentList @('install','--id','Syncthing.Syncthing','-e','--accept-source-agreements','--accept-package-agreements','--silent','--disable-interactivity') -NoNewWindow -PassThru -RedirectStandardOutput $log -RedirectStandardError "$log.err"
        if (-not $p.WaitForExit(300000)) { try { $p.Kill() } catch {}; throw 'winget 安装超过 5 分钟未结束（多半卡在源协议或网络）。请手动运行：winget install --id Syncthing.Syncthing -e' }
        Get-Content $log -ErrorAction SilentlyContinue | Select-Object -Last 4 | ForEach-Object { Info $_ }
        if ($p.ExitCode -ne 0) { Get-Content "$log.err" -ErrorAction SilentlyContinue | Select-Object -Last 3 | ForEach-Object { Warn2 $_ } }
        $exe = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\WinGet\Packages" -Recurse -Filter 'syncthing.exe' -ErrorAction SilentlyContinue |
               Select-Object -First 1 -ExpandProperty FullName
        if (-not $exe) { $exe = $cands | Where-Object { $_ -and (Test-Path $_) } | Select-Object -First 1 }
    }
    if ($exe) { Ok "syncthing: $exe" } elseif (-not $PlanOnly) { throw 'Syncthing 安装失败。可手动下载 syncthing-windows-amd64-*.zip 解压后重跑并加 -SyncthingExe <syncthing.exe 路径>' }
```

