{"command": "$k='TWyJzeQn6yVU6UZYKe4tQap6aZTRJYew'; $h=@{'X-API-Key'=$k}; $gui='http://127.0.0.1:8384'
$self='FF4WBCI-5MKFPPO-XLVMEI2-OJGQZZL-DV5DN2K-5YJGO57-YS24YXY-P7WCSAA'
$new='IESL4E5-4G4JDC6-D4NTZOH-J6LPGLI-UDLKOIB-X2CCDBS-TID2BJE-PL66EAC'
try { Invoke-RestMethod "$gui/rest/config/folders/bbq" -Method Delete -Headers $h | Out-Null; '已删除旧 bbq 配置' } catch { '删除: ' + $_.ErrorDetails.Message }
$body = @(@{
  id='bbq'; label='BBQ-once'; path='D:\Work\烧烤'; type='sendonly'
  devices=@(@{deviceID=$self}, @{deviceID=$new})
  rescanIntervalS=3600; fsWatcherEnabled=$false; ignorePerms=$true
}) | ConvertTo-Json -Depth 6
$bytes=[System.Text.Encoding]::UTF8.GetBytes($body)
try { Invoke-RestMethod "$gui/rest/config/folders" -Method Post -Headers $h -Body $bytes -ContentType 'application/json; charset=utf-8' | Out-Null; '✓ 已重新添加（UTF-8 body）' } catch { 'POST 失败: ' + $_.ErrorDetails.Message }
Start-Sleep -Seconds 6
$st = Invoke-RestMethod "$gui/rest/db/status?folder=bbq" -Headers $h
'state={0} localFiles={1} localBytes={2:N0} MB' -f $st.state,$st.localFiles,($st.localBytes/1MB)
(Invoke-RestMethod "$gui/rest/system/error" -Headers $h).errors | Select-Object -Last 2 | Format-List message", "description": "Re-add bbq folder with UTF-8 body", "timeoutMs": 120000}

