content.arguments:
{"command": "$p='D:\Work\兵哥烧烤\meituan-agent\setup_tasks.ps1'
$t=[System.IO.File]::ReadAllText($p,[System.Text.Encoding]::UTF8)

$old1 = @'
        $cmd = Get-Command python.exe -ErrorAction SilentlyContinue
        if ($cmd) { $Python = $cmd.Source }
        else { throw '找不到 python.exe：请先打开一次 DSH，或用 -Python 指定路径' }
'@
$new1 = @'
        $cmd = Get-Command python.exe -ErrorAction SilentlyContinue
        if ($cmd -and $cmd.Source -notlike '*\WindowsApps\python.exe') {
            $Python = $cmd.Source
        } elseif ($cmd) {
            throw "只找到应用商店的 python 占位程序（$($cmd.Source)），它不能直接跑脚本。请先打开一次 DSH 生成运行时，或用 -Python 指定真实 python.exe。"
        } else {
            throw '找不到 python.exe：请先打开一次 DSH，或用 -Python 指定路径'
        }
'@
if (-not $t.Contains($old1)) { throw '未找到 python 兜底段' }
$t = $t.Replace($old1,$new1)

$old2 = @'
    # 模板是从"已停用"的任务导出的，导入时必须强制启用
    $x = $x.Replace('<Enabled>false</Enabled>', '<Enabled>true</Enabled>')
'@
$new2 = @'
    # 模板里的 LogonTrigger 还带着旧机器帐户名（如 LINK\24380），换成当前用户
    $x = [regex]::Replace($x, '<UserId>[^<]*\\[^<]*</UserId>', "<UserId>$user</UserId>")
    # 模板是从"已停用"的任务导出的，导入时必须强制启用
    $x = $x.Replace('<Enabled>false</Enabled>', '<Enabled>true</Enabled>')
'@
if (-not $t.Contains($old2)) { throw '未找到 Enabled 段' }
$t = $t.Replace($old2,$new2)

$old3 = @'
    & schtasks.exe /Create /TN $t /XML $tmp /F 2>&1 | Out-Null
    if ($LASTEXITCODE -eq 0) { "✓ $t 已创建" } else { "✗ $t 创建失败（退出码 $LASTEXITCODE）" }
'@
$new3 = @'
    $out = & schtasks.exe /Create /TN $t /XML $tmp /F 2>&1
    if ($LASTEXITCODE -eq 0) { "✓ $t 已创建" }
    else {
        "✗ $t 创建失败（退出码 $LASTEXITCODE）"
        ($out | Where-Object { $_ -is [System.Management.Automation.ErrorRecord] } | ForEach-Object { $_.ToString() }) |
            Select-Object -First 3 | ForEach-Object { "    $_" }
    }
'@
if (-not $t.Contains($old3)) { throw '未找到 schtasks 段' }
$t = $t.Replace($old3,$new3)
[System.IO.File]::WriteAllText($p,$t,(New-Object System.Text.UTF8Encoding($true)))
$err=$null; [void][System.Management.Automation.Language.Parser]::ParseFile($p,[ref]$null,[ref]$err)
if ($err) { 'PARSE FAIL'; $err[0].Message } else { 'setup_tasks parse OK' }
$err2=$null; [void][System.Management.Automation.Language.Parser]::ParseFile('D:\Work\DSH\migrate\Bootstrap-NewPc.ps1',[ref]$null,[ref]$err2)
if ($err2) { 'BOOTSTRAP PARSE FAIL'; $err2[0].Message } else { 'bootstrap parse OK' }", "description": "Patch setup_tasks for UserId and python stub"}

