content.arguments:
{"command": "$k='TWyJzeQn6yVU6UZYKe4tQap6aZTRJYew'; $h=@{'X-API-Key'=$k}; $gui='http://127.0.0.1:8384'
$self='FF4WBCI-5MKFPPO-XLVMEI2-OJGQZZL-DV5DN2K-5YJGO57-YS24YXY-P7WCSAA'
$new='IESL4E5-4G4JDC6-D4NTZOH-J6LPGLI-UDLKOIB-X2CCDBS-TID2BJE-PL66EAC'
$body = @(@{
  id='bundle'; label='DSH-restore-bundle'; path='D:\dsh-bundle'; type='sendonly'
  devices=@(@{deviceID=$self}, @{deviceID=$new})
  rescanIntervalS=3600; fsWatcherEnabled=$true; ignorePerms=$true
}) | ConvertTo-Json -Depth 6
$bytes=[System.Text.Encoding]::UTF8.GetBytes($body)
try { Invoke-RestMethod "$gui/rest/config/folders" -Method Post -Headers $h -Body $bytes -ContentType 'application/json; charset=utf-8' | Out-Null; '✓ 已添加 bundle 文件夹（sendonly）' } catch { 'POST 失败: ' + $_.ErrorDetails.Message }
Start-Sleep -Seconds 8
'--- 各文件夹状态 ---'
foreach ($id in 'work','bbq','bundle') {
  $s=Invoke-RestMethod "$gui/rest/db/status?folder=$id" -Headers $h
  '{0,-7} state={1,-9} local={2,6} 文件 {3,8:N0} MB' -f $id,$s.state,$s.localFiles,($s.localBytes/1MB)
}
'--- 新设备完成度 ---'
foreach ($id in 'work','bbq','bundle') {
  try { $c=Invoke-RestMethod "$gui/rest/db/completion?folder=$id&device=$new" -Headers $h; '{0,-7} {1,5:N1}%  need {2,6:N0} MB' -f $id,$c.completion,($c.needBytes/1MB) } catch { "$id : 新机未接受" }
}", "description": "Add bundle folder and check all folder states", "timeoutMs": 120000}

