content.arguments:
{"file_path": "D:\Work\DSH\migrate\Bootstrap-NewPc.ps1", "old_string": "    $setup = Join-Path $WorkRoot '兵哥烧烤\meituan-agent\setup_tasks.ps1'
    if (Test-Path $setup) {
        if ($PlanOnly) { Info "将执行: $setup -WorkRoot $WorkRoot" }
        else {
            & powershell -NoProfile -ExecutionPolicy Bypass -File $setup -WorkRoot $WorkRoot
            if ($LASTEXITCODE -eq 0) { Ok '采集任务已创建' }
            else {
                Warn2 "采集任务没建成（退出码 $LASTEXITCODE）。多半是 python 还没生成：打开一次 DSH 后，重跑"
                Warn2 "  powershell -ExecutionPolicy Bypass -File `"$setup`""
            }
        }
    } else {
        Warn2 "还没同步到 $setup —— 等 Syncthing 把文件拉下来后再跑这一步"
    }", "new_string": "    $setup = Join-Path $WorkRoot '兵哥烧烤\meituan-agent\setup_tasks.ps1'
    $rtPy  = Join-Path $env:USERPROFILE '.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe'
    if (-not (Test-Path $setup)) {
        Warn2 "还没同步到 $setup —— 等 Syncthing 把文件拉下来后再跑这一步"
    } elseif (-not (Test-Path $rtPy) -and -not $PlanOnly) {
        # 没有运行时 python 时硬跑，会拿应用商店占位程序建出一堆跑不起来的人物，不如先跳过
        Warn2 '运行时 python 还没生成，跳过建任务（否则任务会指向 WindowsApps 里的占位程序）'
        Warn2 '  先在 DSH 里随便让它执行一条命令（例如 Get-Location）触发运行时解压，然后重跑：'
        Warn2 "  powershell -ExecutionPolicy Bypass -File `"$setup`""
    } else {
        if ($PlanOnly) { Info "将执行: $setup -WorkRoot $WorkRoot" }
        else {
            & powershell -NoProfile -ExecutionPolicy Bypass -File $setup -WorkRoot $WorkRoot
            if ($LASTEXITCODE -eq 0) { Ok '采集任务已创建' }
            else {
                Warn2 "采集任务没建成（退出码 $LASTEXITCODE），看上面每条的 ✗ 原因；补好 python 后重跑："
                Warn2 "  powershell -ExecutionPolicy Bypass -File `"$setup`""
            }
        }
    }"}

